<div class="space-y-6"><div><h2 class="font-display text-2xl font-bold tracking-tight">Recent Orders</h2><p class="text-sm text-muted-foreground mt-0.5">Track your latest sales and customer downloads.</p></div><div class="bg-card border border-border rounded-2xl overflow-hidden shadow-sm"><div class="overflow-x-auto"><table class="w-full text-left border-collapse min-w-[900px]"><thead><tr class="border-b border-border bg-secondary/20"><th class="py-4 px-6 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Order ID</th><th class="py-4 px-6 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Customer</th><th class="py-4 px-6 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Products</th><th class="py-4 px-6 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Status</th><th class="py-4 px-6 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Amount</th></tr></thead><tbody class="divide-y divide-border/50"><?php foreach (($orders ?? []) as $order): ?><tr class="hover:bg-secondary/10 transition-colors"><td class="py-4 px-6"><div class="font-mono text-xs font-bold"><?= e((string) ($order['id'] ?? '')) ?></div><div class="text-[10px] text-muted-foreground mt-1"><?= e((string) ($order['date'] ?? '')) ?></div></td><td class="py-4 px-6"><div class="font-bold text-sm"><?= e((string) ($order['name'] ?? '')) ?></div><div class="text-[10px] text-muted-foreground"><?= e((string) ($order['email'] ?? '')) ?></div></td><td class="py-4 px-6"><div class="text-xs font-medium max-w-[200px] truncate"><?= e((string) ($order['prods'] ?? '')) ?></div></td><td class="py-4 px-6"><span class="px-2 py-1 rounded text-[10px] font-bold <?= strtolower((string) ($order['status'] ?? '')) === 'paid' ? 'bg-emerald-500/10 text-emerald-500' : (strtolower((string) ($order['status'] ?? '')) === 'pending' ? 'bg-amber-500/10 text-amber-500' : 'bg-secondary text-muted-foreground') ?>"><?= e((string) ($order['status'] ?? '')) ?></span></td><td class="py-4 px-6"><div class="font-display text-sm font-bold"><?= e((string) ($order['price'] ?? '')) ?></div></td></tr><?php endforeach; ?></tbody></table></div></div></div>
